package org.slavicmyths.verify;

import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.monster.Zombie;
import net.minecraft.world.level.GameType;
import net.minecraft.world.item.*;
import net.minecraft.world.effect.*;
import net.minecraft.nbt.CompoundTag;
import net.neoforged.neoforge.gametest.*;
import org.slavicmyths.rpg.classes.*;
import org.slavicmyths.rpg.PathData;

@GameTestHolder("slavicmyths_classes") @PrefixGameTestTemplate(false)
public final class Classes3GameTests {
    private static final class Connection extends net.minecraft.network.Connection {
        private final io.netty.channel.embedded.EmbeddedChannel channel=new io.netty.channel.embedded.EmbeddedChannel();
        Connection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}
        @Override public io.netty.channel.Channel channel(){return channel;}
    }
    private static final class Listener extends net.minecraft.server.network.ServerGamePacketListenerImpl {
        Listener(ServerPlayer p){super(p.getServer(),new Connection(),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));}
        @Override public void send(net.minecraft.network.protocol.Packet<?> packet){}
        @Override public void send(net.minecraft.network.protocol.Packet<?> packet,net.minecraft.network.PacketSendListener listener){}
    }
    private static ServerPlayer player(GameTestHelper h,String base){var p=new ServerPlayer(h.getLevel().getServer(),h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"C3Fixture"),ClientInformation.createDefault());p.connection=new Listener(p);p.setGameMode(GameType.SURVIVAL);p.setNoGravity(true);p.moveTo(h.absoluteVec(new net.minecraft.world.phys.Vec3(3,2,3)));ClassState.choose(p,base);return p;}
    private static void branch(ServerPlayer p,String second){var d=ClassState.data(p);var b=ClassDefinitions.BRANCHES.get(second);d.putInt("Level",40);d.putString("First",b.parent());d.putString("Second",second);}
    private static Zombie enemy(GameTestHelper h,ServerPlayer p){var z=EntityType.ZOMBIE.create(h.getLevel());z.setNoAi(true);z.setNoGravity(true);z.setPersistenceRequired();z.moveTo(p.getX(),p.getY(),p.getZ()+2);z.setTarget(p);h.getLevel().addFreshEntity(z);return z;}
    @GameTest(template="empty") public static void c3MigrationAndSlots(GameTestHelper h){for(String base:ClassDefinitions.BASES){var p=player(h,base);var d=ClassState.data(p);d.putInt("Version",2);d.putLong("Xp",77);d.putInt("Points",9);String passive=base.equals("druzhinnik")?"temper":base.equals("vedun")?"ward_power":"light_step";d.getCompound("Ranks").putInt(passive,3);d.putString("Passive",passive);d.getCompound("Cooldowns").putLong("lunge",123456);var old=d.copy();ClassState.data(p);h.assertTrue(d.getInt("Version")==3&&d.getLong("Xp")==77&&d.getInt("Points")==9&&d.getString("Passive").equals(passive)&&d.getCompound("Cooldowns").equals(old.getCompound("Cooldowns")),"v2 data lost");h.assertTrue(!ClassState.equip(p,passive,4),"locked slot allowed");String second=ClassDefinitions.BRANCHES.values().stream().filter(b->b.base().equals(base)&&b.level()==25).findFirst().get().id();branch(p,second);h.assertTrue(!ClassState.equip(p,passive,4),"duplicate passive allowed");var copy=ClassState.data(p).copy();PathData.data(p).put("Class2",copy);h.assertTrue(ClassState.data(p).equals(copy),"idempotent load changed data");}h.succeed();}
    @GameTest(template="empty") public static void c3PassiveMatrix(GameTestHelper h){for(String id:List.of("battle_discipline","iron_will","spiritual_fortitude","sign_mastery","ambush_master","survival_instinct")){var s=ClassDefinitions.SKILLS.get(id);var p=player(h,s.base());String second=ClassDefinitions.BRANCHES.values().stream().filter(b->b.base().equals(s.base())&&b.level()==25).findFirst().get().id();branch(p,second);var d=ClassState.data(p);for(int rank=1;rank<=3;rank++){d.getCompound("Ranks").putInt(id,rank);h.assertTrue(ClassState.passive(p,id)==0,"unequipped passive active");h.assertTrue(ClassState.equip(p,id,3)&&ClassState.passive(p,id)==rank,"first slot rank");ClassState.equip(p,"",3);h.assertTrue(ClassState.equip(p,id,4)&&ClassState.passive(p,id)==rank,"second slot rank");d.putInt("Level",24);h.assertTrue(ClassState.passive(p,id)==0,"locked bonus applied");d.putInt("Level",40);ClassState.equip(p,"",4);}}h.succeed();}
    @GameTest(template="empty") public static void c3XpLedger(GameTestHelper h){for(String base:ClassDefinitions.BASES){var p=player(h,base);int vanilla=p.experienceLevel;h.assertTrue(ClassXpService.once(p,ClassXpService.AwardSource.STORY,"real",200),"first XP missing");long xp=ClassState.data(p).getLong("Xp");h.assertTrue(!ClassXpService.once(p,ClassXpService.AwardSource.STORY,"real",200)&&ClassState.data(p).getLong("Xp")==xp,"duplicate reward");p.setGameMode(GameType.CREATIVE);h.assertTrue(!ClassXpService.once(p,ClassXpService.AwardSource.STORY,"fake",200),"creative XP");p.setGameMode(GameType.SURVIVAL);var z=enemy(h,p);h.assertTrue(ClassXpService.role(p,"hit",z)&&!ClassXpService.role(p,"hit",z),"role throttle");h.assertTrue(p.experienceLevel==vanilla,"vanilla XP changed");z.discard();}h.succeed();}
    @GameTest(template="empty") public static void c3NativeKillAndArtificial(GameTestHelper h){var p=player(h,"druzhinnik");var z=enemy(h,p);z.hurt(p.damageSources().playerAttack(p),100);h.assertTrue(ClassState.data(p).getInt("XpWindowCOMBATUsed")==12,"native kill XP");var artificial=enemy(h,p);artificial.getPersistentData().putBoolean("ClassXpArtificial",true);artificial.hurt(p.damageSources().playerAttack(p),100);h.assertTrue(ClassState.data(p).getInt("XpWindowCOMBATUsed")==12,"artificial kill XP");h.succeed();}
    @GameTest(template="empty") public static void c3TrialAuthority(GameTestHelper h){for(var u:ClassUltimates.ALL.values()){var p=player(h,u.base());branch(p,u.parent());var d=ClassState.data(p);d.putInt("Level",39);ClassTrialService.progress(p,u.parent(),100,null,true);h.assertTrue(d.getCompound("Trials").getDouble(u.parent())==0&&!ClassState.advance(p,u.id()),"early trial/IV");d.putInt("Level",40);for(int n=0;n<15;n++){var trials=d.getCompound("Trials");trials.putLong("LastCombat",ClassState.now(p)-201);ClassTrialService.progress(p,u.parent(),100,null,true);}h.assertTrue(ClassTrialService.completed(d,u.parent()),"trial threshold "+u.parent());h.assertTrue(ClassState.advance(p,u.id())&&ClassUltimates.selected(d)==u,"IV mapping "+u.id());h.assertTrue(!ClassState.advance(p,u.id()),"repeat IV");}h.succeed();}
    @GameTest(template="empty") public static void c3DebuffAndCooldown(GameTestHelper h){var p=player(h,"vedun");branch(p,"oberezhnik");var d=ClassState.data(p);d.getCompound("Ranks").putInt("spiritual_fortitude",3);ClassState.equip(p,"spiritual_fortitude",3);p.addEffect(new MobEffectInstance(MobEffects.POISON,100,0));h.assertTrue(p.getEffect(MobEffects.POISON).getDuration()==80,"debuff shortening");d.getCompound("Ranks").putInt("sign_mastery",3);ClassState.equip(p,"sign_mastery",4);h.assertTrue(ClassBalance.duration(d,"binding_sign",1)==35,"sign duration");var warrior=player(h,"druzhinnik");branch(warrior,"bogatyr");var w=ClassState.data(warrior);w.getCompound("Ranks").putInt("battle_discipline",3);ClassState.equip(warrior,"battle_discipline",3);h.assertTrue(ClassBalance.cooldown(w,"trip",1)==223&&ClassBalance.cooldown(w,"lunge",1)==160,"discipline scope");h.succeed();}
    private static void unlock(ServerPlayer p,ClassUltimates.Definition u){branch(p,u.parent());var d=ClassState.data(p);var trials=new CompoundTag();trials.putBoolean(u.parent()+"Done",true);d.put("Trials",trials);ClassState.advance(p,u.id());}
    @GameTest(template="empty") public static void c3UltimateAuthority(GameTestHelper h){for(var u:ClassUltimates.ALL.values()){var p=player(h,u.base());h.assertTrue(!ClassUltimateRuntime.activate(p),"locked ultimate accepted");unlock(p,u);h.assertTrue(ClassUltimates.selected(ClassState.data(p))==u,"selected ultimate missing");p.setGameMode(GameType.SPECTATOR);h.assertTrue(!ClassUltimateRuntime.activate(p),"spectator ultimate");p.setGameMode(GameType.SURVIVAL);ClassState.cooldown(p,u.skill(),100);h.assertTrue(!ClassUltimateRuntime.activate(p),"cooldown ignored");ClassUltimateRuntime.clear(p);}h.succeed();}
    @GameTest(template="empty") public static void c3WaterHeal(GameTestHelper h){var p=player(h,"vedun");h.getLevel().addNewPlayer(p);try{unlock(p,ClassUltimates.ALL.get("zhivotvorets"));p.setHealth(10);h.assertTrue(ClassUltimateRuntime.activate(p),"water failed");h.assertTrue(p.getHealth()==16&&ClassState.remaining(p,"living_water")==2400,"water actual heal/CD");ClassUltimateRuntime.clear(p);}finally{h.getLevel().removePlayerImmediately(p,Entity.RemovalReason.DISCARDED);}h.succeed();}
    @GameTest(template="empty") public static void c3ShadowAndMarks(GameTestHelper h){var p=player(h,"vedun");unlock(p,ClassUltimates.ALL.get("tainoved"));p.setHealth(7);h.assertTrue(!ClassUltimateRuntime.activate(p)&&p.getHealth()==7,"invalid pact cost");p.setHealth(20);var z=enemy(h,p);p.setYRot(0);p.setXRot(0);h.assertTrue(ClassUltimateRuntime.activate(p)&&p.getHealth()==16,"pact registration/cost");ClassUltimateRuntime.clear(p);z.discard();h.succeed();}
    @GameTest(template="empty") public static void c3FlurryAndArrow(GameTestHelper h){
        var p=player(h,"druzhinnik");unlock(p,ClassUltimates.ALL.get("master_sechi"));p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_SWORD));var z=enemy(h,p);var other=enemy(h,p);other.moveTo(z.getX()+1,z.getY(),z.getZ());h.assertTrue(ClassUltimateRuntime.activate(p),"flurry cast");z.hurt(p.damageSources().playerAttack(p),4);h.assertTrue(other.getHealth()<20,"flurry arc did not damage extra target");ClassUltimateRuntime.clear(p);z.discard();other.discard();
        var archer=player(h,"razboinik");unlock(archer,ClassUltimates.ALL.get("sokoliny_glaz"));var target=enemy(h,archer);archer.setYRot(0);archer.setXRot(0);h.assertTrue(ClassUltimateRuntime.activate(archer),"arrow mark cast");var arrow=new net.minecraft.world.entity.projectile.Arrow(EntityType.ARROW,h.getLevel());arrow.setOwner(archer);target.hurt(archer.damageSources().arrow(arrow,archer),2);h.assertTrue(target.getHealth()<14,"marked arrow bonus absent");ClassUltimateRuntime.clear(archer);target.discard();h.succeed();
    }
    @GameTest(template="empty") public static void c3CircleAndBanner(GameTestHelper h){for(String id:List.of("khranitel_kruga","verkhovny_voevoda")){var u=ClassUltimates.ALL.get(id);var p=player(h,u.base());for(int n=0;n<61;n++)p.tick();h.getLevel().addNewPlayer(p);try{unlock(p,u);var z=enemy(h,p);h.assertTrue(ClassUltimateRuntime.activate(p),"zone cast "+id);float hp=p.getHealth();p.hurt(p.damageSources().mobAttack(z),10);float lost=hp-p.getHealth();h.assertTrue(lost>0&&lost<10,"zone failed to prevent damage "+id+" lost="+lost);ClassUltimateRuntime.clear(p);z.discard();}finally{h.getLevel().removePlayerImmediately(p,Entity.RemovalReason.DISCARDED);}}h.succeed();}
    @GameTest(template="empty") public static void c3DashCollision(GameTestHelper h){var p=player(h,"razboinik");unlock(p,ClassUltimates.ALL.get("vikhrevoy_naletchik"));p.setOnGround(true);p.setYRot(0);p.setXRot(0);double before=p.getZ();h.assertTrue(ClassUltimateRuntime.activate(p)&&p.getZ()>before+2,"first physical dash");p.setOnGround(true);h.assertTrue(ClassUltimateRuntime.activate(p)&&p.getZ()>before+5,"second dash");p.setOnGround(true);h.assertTrue(!ClassUltimateRuntime.activate(p),"third dash bypassed cooldown");ClassUltimateRuntime.clear(p);h.succeed();}
    @GameTest(template="empty",timeoutTicks=100) public static void c3DecoyCleanup(GameTestHelper h){var p=player(h,"razboinik");h.getLevel().addNewPlayer(p);try{unlock(p,ClassUltimates.ALL.get("tenevoy_ataman"));var z=enemy(h,p);h.assertTrue(ClassUltimateRuntime.activate(p),"decoy cast");var decoy=z.getTarget();h.assertTrue(decoy!=null&&decoy!=p&&!decoy.isRemoved(),"native decoy target missing");ClassUltimateRuntime.clear(p);h.assertTrue(decoy.isRemoved()&&z.getTarget()==p,"decoy cleanup/target restore");z.discard();}finally{h.getLevel().removePlayerImmediately(p,Entity.RemovalReason.DISCARDED);}h.succeed();}
    @GameTest(template="empty",timeoutTicks=100) public static void c3PlagueBloodAndPactTicks(GameTestHelper h){var players=new ArrayList<ServerPlayer>();var mobs=new ArrayList<Zombie>();for(String id:List.of("povelitel_mora","tainoved","krovnik")){var u=ClassUltimates.ALL.get(id);var p=player(h,u.base());unlock(p,u);var z=enemy(h,p);if(id.equals("krovnik")){// Blood mark intentionally rejects undead.
                h.assertTrue(!ClassUltimateRuntime.activate(p),"blood mark accepted undead");z.discard();ClassUltimateRuntime.clear(p);continue;}
            p.setYRot(0);p.setXRot(0);h.assertTrue(ClassUltimateRuntime.activate(p),"timed cast "+id);players.add(p);mobs.add(z);}
        for(int tick=1;tick<=45;tick++)h.runAfterDelay(tick,()->{for(var p:players)ClassUltimateRuntime.tick(p);});h.runAfterDelay(46,()->{for(int i=0;i<mobs.size();i++){h.assertTrue(mobs.get(i).getHealth()<20,"timed damage absent "+i);ClassUltimateRuntime.clear(players.get(i));mobs.get(i).discard();}h.succeed();});
    }
    @GameTest(template="empty") public static void c3EarthThunder(GameTestHelper h){var p=player(h,"druzhinnik");unlock(p,ClassUltimates.ALL.get("gromoboy"));var z=enemy(h,p);p.setOnGround(true);h.assertTrue(ClassUltimateRuntime.activate(p),"earth registration");p.setOnGround(false);ClassUltimateRuntime.tick(p);p.setOnGround(true);ClassUltimateRuntime.tick(p);h.assertTrue(z.getHealth()<14,"earth landing did not hit");ClassUltimateRuntime.clear(p);z.discard();h.succeed();}
    @GameTest(template="empty",timeoutTicks=240) public static void c3BloodCharges(GameTestHelper h){var p=player(h,"razboinik");unlock(p,ClassUltimates.ALL.get("krovnik"));var spider=EntityType.SPIDER.create(h.getLevel());spider.setNoAi(true);spider.setNoGravity(true);spider.moveTo(p.getX(),p.getY(),p.getZ()+2);spider.setTarget(p);h.getLevel().addFreshEntity(spider);p.setYRot(0);p.setXRot(30);h.assertTrue(ClassUltimateRuntime.activate(p),"blood registration");for(int tick:List.of(2,14,26,38))h.runAfterDelay(tick,()->spider.hurt(p.damageSources().playerAttack(p),1));for(int tick=1;tick<=180;tick++)h.runAfterDelay(tick,()->ClassUltimateRuntime.tick(p));h.runAfterDelay(181,()->{h.assertTrue(spider.getHealth()<10,"blood charges/bleeding absent");ClassUltimateRuntime.clear(p);spider.discard();h.succeed();});}
    @GameTest(template="empty") public static void c3LivingWall(GameTestHelper h){var p=player(h,"druzhinnik");for(int n=0;n<61;n++)p.tick();h.getLevel().addNewPlayer(p);try{unlock(p,ClassUltimates.ALL.get("nesokrushimy"));p.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,new ItemStack(Items.SHIELD));p.startUsingItem(net.minecraft.world.InteractionHand.OFF_HAND);for(int n=0;n<7;n++)p.doTick();p.setYRot(0);p.setXRot(0);var z=enemy(h,p);var ally=EntityType.VILLAGER.create(h.getLevel());ally.setNoAi(true);ally.setNoGravity(true);ally.moveTo(p.getX(),p.getY(),p.getZ()-1);h.getLevel().addFreshEntity(ally);h.assertTrue(ClassUltimateRuntime.activate(p),"wall registration");ally.hurt(p.damageSources().mobAttack(z),10);h.assertTrue(ally.getHealth()>12.9&&ally.getHealth()<13.1,"directional wall actual damage "+ally.getHealth());ClassUltimateRuntime.clear(p);ally.discard();z.discard();}finally{h.getLevel().removePlayerImmediately(p,Entity.RemovalReason.DISCARDED);}h.succeed();}
    @GameTest(template="empty") public static void c3InstinctAndAmbushRanks(GameTestHelper h){for(int rank=1;rank<=3;rank++){var p=player(h,"razboinik");for(int n=0;n<61;n++)p.tick();branch(p,"reznik");var d=ClassState.data(p);d.getCompound("Ranks").putInt("survival_instinct",rank);ClassState.equip(p,"survival_instinct",3);p.hurt(p.damageSources().generic(),7);double speed=p.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED);h.assertTrue(Math.abs(speed/.1-(1+ClassDefinitions.SKILLS.get("survival_instinct").power(rank)))<.00001,"instinct rank "+rank);h.assertTrue(ClassState.remaining(p,"survival_instinct")==1200,"instinct cooldown");ClassState.equip(p,"",3);ClassPassiveEvents.tick(p);h.assertTrue(Math.abs(p.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED)-.1)<.00001,"unequipped instinct retained");d.getCompound("Ranks").putInt("ambush_master",rank);ClassState.equip(p,"ambush_master",3);var z=enemy(h,p);z.setTarget(null);z.hurt(p.damageSources().playerAttack(p),4);float first=20-z.getHealth();z.setHealth(20);z.invulnerableTime=0;z.hurt(p.damageSources().playerAttack(p),4);h.assertTrue(first>20-z.getHealth(),"opener repeated/missing rank "+rank);z.discard();}h.succeed();}
    @GameTest(template="empty") public static void c3IronWillRanks(GameTestHelper h){var difficulty=h.getLevel().getDifficulty();try{h.getLevel().getServer().setDifficulty(net.minecraft.world.Difficulty.NORMAL,true);for(int rank=1;rank<=3;rank++){var p=player(h,"druzhinnik");for(int n=0;n<61;n++)p.tick();var d=ClassState.data(p);d.getCompound("Ranks").putInt("iron_will",rank);ClassState.equip(p,"iron_will",3);p.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,new ItemStack(Items.SHIELD));p.setYRot(0);p.startUsingItem(net.minecraft.world.InteractionHand.OFF_HAND);for(int n=0;n<6;n++)p.doTick();var z=enemy(h,p);p.hurt(p.damageSources().mobAttack(z),5);ClassEvents.tick(new net.neoforged.neoforge.event.tick.PlayerTickEvent.Post(p));h.assertTrue(ClassState.remaining(p,"iron_will")==400,"confirmed block did not arm iron will");p.stopUsingItem();p.invulnerableTime=0;float hp=p.getHealth();p.hurt(p.damageSources().generic(),10);float expected=(float)(10*(1-ClassDefinitions.SKILLS.get("iron_will").power(rank)));h.assertTrue(Math.abs(hp-p.getHealth()-expected)<.001,"iron will reduction rank "+rank);z.discard();}}finally{h.getLevel().getServer().setDifficulty(difficulty,true);}h.succeed();}
    @GameTest(template="empty") public static void c3RemainingPassiveRanks(GameTestHelper h){for(int rank=1;rank<=2;rank++){var p=player(h,"vedun");branch(p,"oberezhnik");var d=ClassState.data(p);d.getCompound("Ranks").putInt("spiritual_fortitude",rank);ClassState.equip(p,"spiritual_fortitude",3);p.addEffect(new MobEffectInstance(MobEffects.POISON,100,0));h.assertTrue(p.getEffect(MobEffects.POISON).getDuration()==(rank==1?90:85),"fortitude rank "+rank);d.getCompound("Ranks").putInt("sign_mastery",rank);ClassState.equip(p,"sign_mastery",4);h.assertTrue(ClassBalance.duration(d,"binding_sign",1)==(rank==1?32:34),"sign rank "+rank);var w=player(h,"druzhinnik");ClassState.data(w).getCompound("Ranks").putInt("battle_discipline",rank);ClassState.equip(w,"battle_discipline",3);h.assertTrue(ClassBalance.cooldown(ClassState.data(w),"trip",1)==(rank==1?233:228),"discipline rank "+rank);}h.succeed();}
    @GameTest(template="empty") public static void c3NewDeathPersistence(GameTestHelper h){var p=player(h,"druzhinnik");unlock(p,ClassUltimates.ALL.get("gromoboy"));var d=ClassState.data(p);d.getCompound("Ranks").putInt("temper",3);d.getCompound("Ranks").putInt("iron_will",2);ClassState.equip(p,"temper",3);ClassState.equip(p,"iron_will",4);d.putLong("Xp",77);ClassState.cooldown(p,"earth_thunder",12000);ClassXpService.ledger(p).putBoolean("STORY:death",true);var expected=d.copy();p.setRespawnPosition(h.getLevel().dimension(),h.absolutePos(new net.minecraft.core.BlockPos(3,2,3)),0,true,false);p.kill();var next=h.getLevel().getServer().getPlayerList().respawn(p,false,Entity.RemovalReason.KILLED);next.connection.player=next;try{h.assertTrue(ClassState.data(next).equals(expected),"new fields lost on actual death/clone");h.assertTrue(ClassState.passive(next,"iron_will")==2&&ClassUltimates.selected(ClassState.data(next)).id().equals("gromoboy")&&next.getMaxHealth()==24,"new loadout not restored");}finally{h.getLevel().getServer().getPlayerList().remove(next);}h.succeed();}
    @GameTest(template="empty") public static void c3DiskRestart(GameTestHelper h){String phase=System.getProperty("slavicmyths.classes3Phase","both");var w=h.getLevel();var p=new ServerPlayer(w.getServer(),w,new com.mojang.authlib.GameProfile(UUID.fromString("43e3530a-a610-40a1-85e0-130000000003"),"C3Disk"),ClientInformation.createDefault());p.connection=new Listener(p);var file=java.nio.file.Path.of("classes3-restart.nbt");try{
        if(!phase.equals("verify")){ClassState.choose(p,"druzhinnik");unlock(p,ClassUltimates.ALL.get("gromoboy"));var d=ClassState.data(p);d.getCompound("Ranks").putInt("temper",3);d.getCompound("Ranks").putInt("iron_will",2);ClassState.equip(p,"temper",3);ClassState.equip(p,"iron_will",4);ClassState.cooldown(p,"earth_thunder",12000);d.putLong("Xp",77);d.putInt("Points",11);ClassXpService.ledger(p).putBoolean("STORY:disk",true);d.getCompound("Trials").putDouble("bogatyr",3);net.minecraft.nbt.NbtIo.writeCompressed(d.copy(),file);w.getServer().getPlayerList().remove(p);System.out.println("CLASSES3_NATIVE_DISK_WRITE_PASS");}
        if(!phase.equals("write")){var expected=net.minecraft.nbt.NbtIo.readCompressed(file,net.minecraft.nbt.NbtAccounter.unlimitedHeap());h.assertTrue(w.getServer().getPlayerList().load(p).isPresent(),"Class3 native player .dat missing");ClassEvents.login(new net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedInEvent(p));h.assertTrue(ClassState.data(p).equals(expected),"Class3 native persisted state lost");h.assertTrue(p.getMaxHealth()==24&&ClassState.passive(p,"iron_will")==2&&ClassState.remaining(p,"earth_thunder")>0,"Class3 loaded attributes/slot/CD");System.out.println("CLASSES3_NATIVE_DISK_"+(phase.equals("verify")?"NEW_PROCESS":"SAME_PROCESS")+"_PASS");}h.succeed();
        }catch(java.io.IOException error){throw new RuntimeException(error);}}
}
